import unittest
from collections import deque
import warehouse_fleet.pathfinding as pf
from warehouse_fleet.model import GridMap, Position

def run():
    loader = unittest.TestLoader()
    suite = loader.loadTestsFromName("tests.test_pathfinding")
    result = unittest.TextTestRunner(verbosity=0).run(suite)
    return result.wasSuccessful()

original = pf.shortest_path

# Mutant 1: longer route — BFS but insert a two-step wiggle before goal
def detour_mutant(grid, start, goal):
    p = original(grid, start, goal)
    return p  # control
pf.shortest_path = detour_mutant
import warehouse_fleet
warehouse_fleet.shortest_path = pf.shortest_path
print("control (unmutated):", run())

# Mutant 2: reversed direction priority (down, right, left, up)
def reordered(grid: GridMap, start: Position, goal: Position):
    if not grid.traversable(start) or not grid.traversable(goal):
        raise ValueError("x")
    if start == goal: return []
    queue = deque([start]); previous = {start: None}
    while queue:
        cur = queue.popleft(); x,y = cur
        for nb in ((x,y+1),(x+1,y),(x-1,y),(x,y-1)):
            if grid.traversable(nb) and nb not in previous:
                previous[nb] = cur
                if nb == goal: queue.clear(); break
                queue.append(nb)
    if goal not in previous: raise ValueError("no route")
    path=[]; c=goal
    while c!=start:
        path.append(c); c=previous[c]
    path.reverse(); return path
pf.shortest_path = reordered; warehouse_fleet.shortest_path = reordered
print("tie-order reversed:", run())

# Mutant 3: returns [] for unreachable instead of raising
def silent_empty(grid, start, goal):
    try: return original(grid, start, goal)
    except ValueError: return []
pf.shortest_path = silent_empty; warehouse_fleet.shortest_path = silent_empty
print("unreachable -> []:", run())

# Mutant 4: greedy non-shortest (always picks neighbor minimizing manhattan, else first) — takes dead ends?
def greedy(grid, start, goal):
    if not grid.traversable(start) or not grid.traversable(goal): raise ValueError("x")
    if start==goal: return []
    path=[]; cur=start; seen={start}
    while cur!=goal:
        nbs=grid.neighbors(cur)
        nbs=[n for n in nbs if n not in seen]
        if not nbs: raise ValueError("stuck")
        nbs.sort(key=lambda n: abs(n[0]-goal[0])+abs(n[1]-goal[1]))
        cur=nbs[0]; seen.add(cur); path.append(cur)
    return path
pf.shortest_path = greedy; warehouse_fleet.shortest_path = greedy
print("greedy walk:", run())

# Mutant 5: skips traversable check on identical endpoints
def same_bypass(grid, start, goal):
    if start == goal: return []
    return original(grid, start, goal)
pf.shortest_path = same_bypass; warehouse_fleet.shortest_path = same_bypass
print("same-endpoint bypass:", run())
