import tests.test_pathfinding as tp

original = pf.shortest_path

def run():
    suite = unittest.TestLoader().loadTestsFromModule(tp)
    return unittest.TextTestRunner(verbosity=0).run(suite).wasSuccessful()

tp.shortest_path = original
print("control (unmutated):", run())

def reordered(grid, start, goal):
    if not grid.traversable(start) or not grid.traversable(goal):
        raise ValueError("x")
    if start == goal: return []
    queue = deque([start]); previous = {start: None}
