        cur = queue.popleft(); x,y = cur
        for nb in ((x,y+1),(x+1,y),(x-1,y),(x,y-1)):
            if grid.traversable(nb) and nb not in previous:
                previous[nb] = cur
                if nb == goal: queue.clear(); break
                queue.append(nb)
    if goal not in previous: raise ValueError("no route")
    path=[]; c=goal
    while c!=start: path.append(c); c=previous[c]
    path.reverse(); return path
tp.shortest_path = reordered
print("tie-order reversed detected:", not run())

def silent_empty(grid, start, goal):
    try: return original(grid, start, goal)
    except ValueError: return []
tp.shortest_path = silent_empty
print("unreachable->[] detected:", not run())

def greedy(grid, start, goal):
    if not grid.traversable(start) or not grid.traversable(goal): raise ValueError("x")
    if start==goal: return []
    path=[]; cur=start; seen={start}
    while cur!=goal:
        nbs=[n for n in grid.neighbors(cur) if n not in seen]
        if not nbs: raise ValueError("stuck")
        nbs.sort(key=lambda n: abs(n[0]-goal[0])+abs(n[1]-goal[1]))
        cur=nbs[0]; seen.add(cur); path.append(cur)
    return path
tp.shortest_path = greedy
print("greedy/long walk detected:", not run())

def same_bypass(grid, start, goal):
    if start == goal: return []
    return original(grid, start, goal)
tp.shortest_path = same_bypass
print("same-endpoint bypass detected:", not run())

# DFS (finds a route, not shortest)
def dfs(grid, start, goal):
    if not grid.traversable(start) or not grid.traversable(goal): raise ValueError("x")
    if start==goal: return []
    stack=[(start,[start])]; seen={start}
    while stack:
        cur, trail = stack.pop()
        for nb in grid.neighbors(cur):
            if nb in seen: continue
            seen.add(nb)
            if nb==goal:
                p=trail[1:]+[nb]; return p
            stack.append((nb, trail+[nb]))
    raise ValueError("none")
tp.shortest_path = dfs
print("DFS non-shortest detected:", not run())
